&lt;h2 id=&#34;支持的框架&#34;&gt;&lt;a href=&#34;#支持的框架&#34; class=&#34;headerlink&#34; title=&#34;支持的框架&#34;&gt;&lt;/a&gt;支持的框架&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;框架&lt;/th&gt;
&lt;th&gt;检测方式&lt;/th&gt;
&lt;th&gt;协程&lt;/th&gt;
&lt;th&gt;集成方式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Plain PHP&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;默认回退&lt;/td&gt;
&lt;td&gt;Fiber&lt;/td&gt;
&lt;td&gt;Kernel 实例化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Laravel&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Illuminate\Foundation\Application&lt;/code&gt;&lt;/td&gt;
